<?php

declare(strict_types=1);
namespace StageArtCore\Presentation\Admin;
use StageArtCore\Presentation\PublicSite\ProductionLayout;

final class ProductionLayoutAdmin
{
    public function __construct(){add_action('admin_post_stageart_save_production',[$this,'save'],50);}
    public function register():void{add_action('admin_footer',[$this,'footer']);}
    public function footer():void{
        if(($_GET['page']??'')!=='stageart-productions'||!current_user_can('manage_options'))return;
        $sections=ProductionLayout::get((int)($_GET['id']??0));$labels=ProductionLayout::contentLabels();
        echo '<style>.stageart-layout-box{margin:24px 0;padding:16px;background:#fff;border:1px solid #ccd0d4}.stageart-layout-section{margin:16px 0;padding:14px;border:1px solid #dcdcde;background:#f6f7f7}.stageart-layout-slot{display:flex;align-items:center;gap:10px;margin:6px 0;padding:8px;background:#fff;border:1px solid #dcdcde;cursor:move}.stageart-layout-slot select{min-width:280px}.stageart-layout-slot .sa-layout-remove{margin-left:auto}</style>';
        $nonce=wp_create_nonce('stageart_production_layout');
        $json=wp_json_encode($sections,JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES);
        $labelsJson=wp_json_encode($labels,JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES);
        echo '<script>(function(){const f=document.getElementById("stageart-production-form");if(!f)return;let sections='.$json.';const labels='.$labelsJson.';const box=document.createElement("div");box.className="stageart-layout-box";box.innerHTML="<h2>公演ページ・コンテンツ配置</h2><p>Alumniと同じスロット方式で、この公演ページのセクション・表示順を設定します。メニュー構成とは別管理です。</p>";const wrap=document.createElement("div");box.appendChild(wrap);const hidden=document.createElement("input");hidden.type="hidden";hidden.name="stageart_production_layout";box.appendChild(hidden);const nonce=document.createElement("input");nonce.type="hidden";nonce.name="stageart_production_layout_nonce";nonce.value="'.$nonce.'";box.appendChild(nonce);function opts(v){let h="<option value=\"\">選択してください</option>";Object.keys(labels).forEach(k=>{h+="<option value=\""+k+"\""+(v===k?" selected":"")+">"+labels[k]+"</option>"});return h}function sync(){hidden.value=JSON.stringify(sections)}function draw(){wrap.innerHTML="";sections.forEach(function(s,si){const sec=document.createElement("div");sec.className="stageart-layout-section";sec.innerHTML="<p><label>見出し（任意）<br><input class=\"regular-text\" data-heading></label>　<label>表示数 <select data-columns></select></label>　<label>表示方向 <select data-layout><option value=\"horizontal\">横並び</option><option value=\"vertical\">縦並び</option></select></label> <button type=\"button\" class=\"button-link-delete\" data-remove-section>削除</button></p><div class=\"sa-layout-slots\"></div><p><button type=\"button\" class=\"button\" data-add-slot>＋ コンテンツを追加</button></p>";sec.querySelector("[data-heading]").value=s.heading||"";const cs=sec.querySelector("[data-columns]");for(let n=1;n<=20;n++)cs.insertAdjacentHTML("beforeend","<option value=\""+n+"\">"+n+"件</option>");cs.value=String(s.columns||1);sec.querySelector("[data-layout]").value=s.layout||"vertical";const slots=sec.querySelector(".sa-layout-slots");(s.slots||[]).forEach(function(sl,idx){const row=document.createElement("div");row.className="stageart-layout-slot";row.draggable=true;row.dataset.i=idx;row.innerHTML="<span>☰</span><select>"+opts(sl.ref)+"</select><button type=\"button\" class=\"button-link-delete sa-layout-remove\">削除</button>";row.querySelector("select").addEventListener("change",function(){sl.type="link";sl.ref=this.value;sync()});row.querySelector(".sa-layout-remove").onclick=function(){s.slots.splice(idx,1);draw();sync()};row.addEventListener("dragstart",e=>e.dataTransfer.setData("text/plain",String(idx)));row.addEventListener("dragover",e=>e.preventDefault());row.addEventListener("drop",e=>{e.preventDefault();const from=Number(e.dataTransfer.getData("text/plain")),to=Number(row.dataset.i);if(from===to)return;const x=s.slots.splice(from,1)[0];s.slots.splice(to,0,x);draw();sync()});slots.appendChild(row)});sec.querySelector("[data-heading]").oninput=function(){s.heading=this.value;sync()};cs.onchange=function(){s.columns=Number(this.value);sync()};sec.querySelector("[data-layout]").onchange=function(){s.layout=this.value;sync()};sec.querySelector("[data-remove-section]").onclick=function(){sections.splice(si,1);draw();sync()};sec.querySelector("[data-add-slot]").onclick=function(){s.slots=s.slots||[];s.slots.push({type:"link",ref:""});draw();sync()};wrap.appendChild(sec)});}const add=document.createElement("p");add.innerHTML="<button type=\"button\" class=\"button\" data-add-section>＋ セクションを追加</button>";box.appendChild(add);add.querySelector("button").onclick=function(){sections.push({section_id:"new-"+Date.now(),heading:"",columns:1,layout:"vertical",slots:[{type:"link",ref:"summary"}]});draw();sync()};draw();sync();const submit=f.querySelector("button[type=submit]");if(submit)f.insertBefore(box,submit.closest("p")||null)})()</script>';
    }
    public function save():void{
        if(!current_user_can('manage_options'))wp_die('権限がありません。');
        $nonce=isset($_POST['stageart_production_layout_nonce'])?sanitize_text_field(wp_unslash($_POST['stageart_production_layout_nonce'])):'';
        if(!$nonce||!wp_verify_nonce($nonce,'stageart_production_layout'))return;
        $id=(int)($_POST['id']??0);if(!$id||get_post_type($id)!=='stageart_production')return;
        $raw=json_decode(wp_unslash((string)($_POST['stageart_production_layout']??'')),true);if(is_array($raw))ProductionLayout::save($id,$raw);
    }
}
